# Load plot characteristics
northness <- function(asp,slp,units='deg') {
  if (units=='deg') {
    asp <- 2*pi*asp/360
    slp <- 2*pi*slp/360
  }
  cos(asp)*sin(slp)
}

eastness <- function(asp,slp,units='deg') {
  if (units=='deg') {
    asp <- 2*pi*asp/360
    slp <- 2*pi*slp/360
  }
  sin(asp)*sin(slp)
}

plotInfo <- read.csv('data/plot.info.2026.csv')
head(plotInfo)
plotInfo$northness <- northness(plotInfo$Aspect.true,plotInfo$Slope)
plotInfo$eastness <- eastness(plotInfo$Aspect.true,plotInfo$Slope)
